#!/usr/bin/env python3
"""
Manchester editor, track menu: compound items only when there are compounds. With a sequence selected, that
means compounds in the selected window; otherwise on the track. Hides Synthesis cost, Draw > Highlight
Compounds, and Highlight / Zoom / Select all compounds when there are none.

    sudo python3 install-compound-menu-scope.py /opt/baja-apps

Edits mouse-over-highlight.js (backed up as mouse-over-highlight.js.before-compound-scope). Refuses, changing
nothing, if the file differs. Safe to run twice.
"""
import os, shutil, sys
HUNKS = [('\n                ]\n\n                // Compound actions, only when this track HAS compounds -- three dead entries on\n                // an empty track is worse than none. They act on every compound on the track,\n                // which is what "the compounds" means from a track menu; the per-compound\n                // actions live under Compounds ▸.\n                try {\n                    const __cs = (selectedTrack && Array.isArray(selectedTrack.oligos))\n                        ? selectedTrack.oligos.filter(Boolean) : [];\n                    if (__cs.length) {\n                        golist.push({\n                            label: \'Highlight compounds (\' + __cs.length + \')\',\n', '\n                ]\n\n                // Compound actions, only when there ARE compounds -- three dead entries on an\n                // empty track is worse than none. With a sequence selected (markstart..markend)\n                // "the compounds" means the ones in that window, so a window with none shows no\n                // compound items at all (Synthesis cost and Draw > Highlight Compounds included,\n                // below); with no selection it means every compound on the track. The\n                // per-compound actions live under Compounds ▸.\n                const __selRange = (() => {\n                    try {\n                        const a = +selectedTrack.markstart, b = +selectedTrack.markend;\n                        if (isFinite(a) && isFinite(b) && a >= 0 && b > a) return { lo: Math.min(a, b), hi: Math.max(a, b) };\n                    } catch (e) { }\n                    return null;\n                })();\n                const __scopeCs = (() => {\n                    try {\n                        const all = (selectedTrack && Array.isArray(selectedTrack.oligos)) ? selectedTrack.oligos.filter(Boolean) : [];\n                        if (!__selRange) return all;\n                        return all.filter((o) => {\n                            const a = +o.xi, b = (o.xf != null ? +o.xf : +o.xi);\n                            if (!isFinite(a)) return false;\n                            const lo = Math.min(a, isFinite(b) ? b : a), hi = Math.max(a, isFinite(b) ? b : a);\n                            return hi >= __selRange.lo && lo <= __selRange.hi;\n                        });\n                    } catch (e) { return []; }\n                })();\n                try {\n                    const __cs = __scopeCs;\n                    if (__cs.length) {\n                        golist.push({\n                            label: \'Highlight compounds (\' + __cs.length + \')\',\n'), ('\n                                    }\n                                },\n                                {\n                                    label: `Highlight Compounds`,\n                                    click: async () => {\n                                        graph.setMessage(" Highlight compounds ")\n', '\n                                    }\n                                },\n                                // only when there are compounds (in the selected window, if any)\n                                ...(__scopeCs.length ? [{\n                                    label: `Highlight Compounds`,\n                                    click: async () => {\n                                        graph.setMessage(" Highlight compounds ")\n'), ('                                        }\n                                        graph.showSideMenu(null);\n                                    }\n                                }\n\n                            ];\n\n', '                                        }\n                                        graph.showSideMenu(null);\n                                    }\n                                }] : [])\n\n                            ];\n\n'), ("                        },\n                        move: () => { }\n                    },\n                    {\n                        label: 'Synthesis cost',\n                        click: async () => {\n                            // What the compounds on this track cost to make, priced per\n", "                        },\n                        move: () => { }\n                    },\n                    // Only when there are compounds to price (in the selected window, if any).\n                    ...(__scopeCs.length ? [{\n                        label: 'Synthesis cost',\n                        click: async () => {\n                            // What the compounds on this track cost to make, priced per\n"), ("                            await exec('baja/manchester/menu/synthesis-cost.js', graph, selectedTrack, genegraph_panel_layout);\n                        },\n                        move: () => { }\n                    },\n                    {\n                        label: 'Layers ▸',\n                        click: async (scx, scy) => {\n", "                            await exec('baja/manchester/menu/synthesis-cost.js', graph, selectedTrack, genegraph_panel_layout);\n                        },\n                        move: () => { }\n                    }] : []),\n                    {\n                        label: 'Layers ▸',\n                        click: async (scx, scy) => {\n")]
MARK = '__scopeCs'
root = os.path.expanduser(sys.argv[1] if len(sys.argv) > 1 else '~/baja-apps')
if 'A CLICK ON THE PEPTIDE' not in open(os.path.join(root, 'baja/manchester/menu/mouse-over-highlight.js'), encoding='utf-8').read():
    sys.exit('Install install-mutate-reorf.py and install-peptide-click.py first. Nothing was changed.')
p = os.path.join(root, 'baja/manchester/menu/mouse-over-highlight.js')
if not os.path.isfile(p):
    sys.exit('Not found: ' + p)
s = open(p, encoding='utf-8').read()
crlf = '\r\n' in s
s = s.replace('\r\n', '\n')
if MARK in s:
    sys.exit('Already installed: ' + p)
for old, new in HUNKS:
    if s.count(old) != 1:
        sys.exit(p + ' differs from the version this update was made against. Nothing was changed.')
    s = s.replace(old, new, 1)
shutil.copyfile(p, p + '.before-compound-scope')
open(p, 'w', encoding='utf-8', newline='').write(s.replace('\n', '\r\n') if crlf else s)
print('Updated', p)
print('Restart baja-server (it caches scripts), then hard-refresh the editor (Ctrl+Shift+R).')
